const mapa = {
    "estufa/bmp180/temperatura": "temperaturaAr",
    "estufa/dht22/temperatura": "umidadeSolo",
    "estufa/dht22/umidade": "umidadeAr",
    "estufa/ldr/luminosidade": "luminosidade"
};
const topico = msg.topic;
const campo = mapa[topico];
if (!campo) return null;
const valor = Number(msg.payload);
const agora = Date.now();
const janelaMs = 2000;
let leituras = context.get("leituras") || {};

if (!Number.isFinite(valor)) {
    delete leituras[campo];
    context.set("leituras", leituras);
    return null;
}

// Expira agrupamentos incompletos. Se o mesmo sensor publicar novamente,
// descarta o agrupamento antigo para não combinar ciclos distintos.
const temposExistentes = Object.values(leituras).map(leitura => leitura.recebidoEm);
if (temposExistentes.some(t => agora - t > janelaMs) || leituras[campo]) {
    leituras = {};
}
leituras[campo] = { valor: valor, recebidoEm: agora };
context.set("leituras", leituras);

const obrigatorias = ["temperaturaAr", "umidadeSolo", "umidadeAr", "luminosidade"];
if (!obrigatorias.every(nome => leituras[nome])) return null;
const tempos = obrigatorias.map(nome => leituras[nome].recebidoEm);
if (Math.max(...tempos) - Math.min(...tempos) > janelaMs) {
    context.set("leituras", {});
    node.warn("Captura descartada: leituras fora da janela temporal de 2 s.");
    return null;
}

const captura = leituras;
context.set("leituras", {});
const capturado = Math.max(...tempos);
const seq = (flow.get("telemetrySeq") || 0) + 1;
flow.set("telemetrySeq", seq);
msg.headers = { "Content-Type": "application/json" };
msg.payload = {
    deviceId: "esp32-estufa-01",
    observationId: `esp32-estufa-01-${capturado}-${seq}`,
    source: "WOKWI_HIVEMQ_NODE_RED",
    measuredAt: new Date(capturado).toISOString(),
    quality: "VALID",
    values: {
        temperaturaAr: captura.temperaturaAr.valor,
        umidadeSolo: captura.umidadeSolo.valor,
        umidadeAr: captura.umidadeAr.valor,
        luminosidade: captura.luminosidade.valor
    },
    units: {
        temperaturaAr: "°C",
        umidadeSolo: "°C",
        umidadeAr: "%",
        luminosidade: "ADC"
    }
};
node.warn("Enviando captura completa à API: " + JSON.stringify(msg.payload));
return msg;
